calleeMethods:
static inline int connection_based(struct sock *sk) /* <=== connection_based */ 
{
	return sk->sk_type == SOCK_SEQPACKET || sk->sk_type == SOCK_STREAM;
}

static inline int sock_intr_errno(long timeo) /* <=== sock_intr_errno */ 
{
	return timeo == MAX_SCHEDULE_TIMEOUT ? -ERESTARTSYS : -EINTR;
}

static int wait_for_packet(struct sock *sk, int *err, long *timeo_p) /* <=== wait_for_packet */ 
{
	int error;
	DEFINE_WAIT_FUNC(wait, receiver_wake_function);

	prepare_to_wait_exclusive(sk_sleep(sk), &wait, TASK_INTERRUPTIBLE);

	/* Socket errors? */
	error = sock_error(sk);
	if (error)
		goto out_err;

	if (!skb_queue_empty(&sk->sk_receive_queue))
		goto out;

	/* Socket shut down? */
	if (sk->sk_shutdown & RCV_SHUTDOWN)
		goto out_noerr;

	/* Sequenced packets can come disconnected.
	 * If so we report the problem
	 */
	error = -ENOTCONN;
	if (connection_based(sk) &&
	    !(sk->sk_state == TCP_ESTABLISHED || sk->sk_state == TCP_LISTEN))
		goto out_err;

	/* handle signals */
	if (signal_pending(current))
		goto interrupted;

	error = 0;
	*timeo_p = schedule_timeout(*timeo_p);
out:
	finish_wait(sk_sleep(sk), &wait);
	return error;
interrupted:
	error = sock_intr_errno(*timeo_p);
out_err:
	*err = error;
	goto out;
out_noerr:
	*err = 0;
	error = 1;
	goto out;
}

static inline int test_tsk_thread_flag(struct task_struct *tsk, int flag) /* <=== test_tsk_thread_flag */ 
{
	return test_ti_thread_flag(task_thread_info(tsk), flag);
}

static inline long sock_rcvtimeo(const struct sock *sk, bool noblock) /* <=== sock_rcvtimeo */ 
{
	return noblock ? 0 : sk->sk_rcvtimeo;
}

static inline int signal_pending(struct task_struct *p) /* <=== signal_pending */ 
{
	return unlikely(test_tsk_thread_flag(p,TIF_SIGPENDING));
}

static inline wait_queue_head_t *sk_sleep(struct sock *sk) /* <=== sk_sleep */ 
{
	BUILD_BUG_ON(offsetof(struct socket_wq, wait) != 0);
	return &rcu_dereference_raw(sk->sk_wq)->wait;
}

static inline void spin_unlock_irqrestore(spinlock_t *lock, unsigned long flags) /* <=== spin_unlock_irqrestore */ 
{
	raw_spin_unlock_irqrestore(&lock->rlock, flags);
}

static inline int sock_error(struct sock *sk) /* <=== sock_error */ 
{
	int err;
	if (likely(!sk->sk_err))
		return 0;
	err = xchg(&sk->sk_err, 0);
	return -err;
}

